/* ==================== DESKTOP PREMIUM UI (≥ 1280px) ==================== */
@media (min-width: 1280px) {

  body {
    background:
      radial-gradient(circle at top left, rgba(103,232,249,0.10), transparent 30%),
      radial-gradient(circle at bottom right, rgba(59,130,246,0.10), transparent 30%),
      linear-gradient(180deg, #0f172a 0%, #111827 45%, #0b1120 100%);
  }

  .container {
    padding: 34px;
    gap: 24px;
  }

  /* ================= HEADER ================= */

  .header-row {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;

    width: 100%;
    min-height: 110px;

    padding: 26px 34px;

    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 28px;

    background: rgba(15, 23, 42, 0.72);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);

    box-shadow:
      0 10px 40px rgba(0,0,0,0.35),
      inset 0 1px 0 rgba(255,255,255,0.05);

    overflow: hidden;

    pointer-events: none;
  }

  .title-group,
  .title-group *,
  .actions,
  .actions * {
    pointer-events: auto;
  }

  .header-row::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      linear-gradient(90deg,
        rgba(103,232,249,0.08),
        transparent 30%,
        transparent 70%,
        rgba(103,232,249,0.05));
    pointer-events: none;
  }

  /* ================= TITLE AREA ================= */

  .title-group {
    position: relative;
    z-index: 2;

    flex: 1;
    max-width: 70%;

    padding: 0;
    background: transparent;
    border: none;
    box-shadow: none;
  }

  .title {
    font-size: 44px;
    line-height: 1.08;
    font-weight: 800;
    letter-spacing: -0.03em;

    color: #f8fafc;

    margin: 0 0 14px 0;

    white-space: normal;
    overflow: visible;
    text-overflow: unset;
  }

  .subtitle {
    display: inline-flex;
    align-items: center;
    gap: 8px;

    font-size: 15px;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;

    color: #67e8f9;

    margin-bottom: 10px;
  }

  .subtitle::before {
    content: '';
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: #67e8f9;
    box-shadow: 0 0 12px rgba(103,232,249,0.9);
  }

  .sources {
    display: block;

    font-size: 14px;
    line-height: 1.6;

    color: #94a3b8;

    max-width: 1000px;
  }

  .sources a {
    color: #cbd5e1;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .sources a:hover {
    color: #67e8f9;
  }

  /* ================= ACTIONS ================= */

  .actions {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    gap: 12px;

    padding: 10px;

    border-radius: 20px;

    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.06);
  }

  .btn {
    position: relative;

    width: 52px;
    height: 52px;

    border-radius: 16px;
    border: 1px solid rgba(255,255,255,0.08);

    background:
      linear-gradient(180deg,
        rgba(255,255,255,0.08),
        rgba(255,255,255,0.03));

    color: #f8fafc;

    display: flex;
    align-items: center;
    justify-content: center;

    cursor: pointer;

    transition:
      transform 0.2s ease,
      background 0.2s ease,
      border-color 0.2s ease,
      box-shadow 0.2s ease;
  }

  .btn:hover {
    transform: translateY(-2px);

    background:
      linear-gradient(180deg,
        rgba(103,232,249,0.18),
        rgba(255,255,255,0.06));

    border-color: rgba(103,232,249,0.35);

    box-shadow:
      0 10px 24px rgba(0,0,0,0.25),
      0 0 18px rgba(103,232,249,0.18);
  }

  .btn:active {
    transform: scale(0.96);
  }

  .btn svg {
    width: 22px;
    height: 22px;
    fill: currentColor;
  }

  .btn.nav-btn {
    color: #67e8f9;
  }

  .btn.nav-btn svg {
    width: 26px;
    height: 26px;
    stroke: currentColor;
    stroke-width: 2.4;
    fill: none;
  }

  .actions div[style*='width:1px'] {
    width: 1px !important;
    height: 34px !important;
    background: rgba(255,255,255,0.08) !important;
    margin: 0 4px !important;
  }

  /* ================= CHART AREA ================= */

  #full-capture-area {
    position: relative;

    padding: 0;
    overflow: hidden;

    border-radius: 30px;

    background:
      linear-gradient(180deg,
        rgba(255,255,255,0.03),
        rgba(255,255,255,0.015));

    border: 1px solid rgba(255,255,255,0.07);

    box-shadow:
      0 20px 60px rgba(0,0,0,0.35),
      inset 0 1px 0 rgba(255,255,255,0.03);
  }

  #full-capture-area::before {
    content: '';
    position: absolute;
    inset: 0;

    background:
      linear-gradient(180deg,
        rgba(255,255,255,0.04),
        transparent 20%);

    pointer-events: none;
  }

  .chart-container {
    position: relative;

    display: flex;
    justify-content: center;
    align-items: center;

    width: 100%;
    height: 100%;

    padding: 46px;
  }

  .chart-container img {
    width: auto;
    height: auto;

    max-width: 100%;
    max-height: calc(100vh - 270px);

    object-fit: contain;

    border-radius: 18px;

    box-shadow:
      0 25px 60px rgba(0,0,0,0.45),
      0 0 0 1px rgba(255,255,255,0.04);

    transition:
      transform 0.35s ease,
      box-shadow 0.35s ease;
  }

  .chart-container img:hover {
    transform: scale(1.01);

    box-shadow:
      0 35px 80px rgba(0,0,0,0.55),
      0 0 0 1px rgba(103,232,249,0.08);
  }

  /* ================= SCROLLBAR ================= */

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.12);
    border-radius: 999px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: rgba(103,232,249,0.28);
  }
}
